const JR_MOT_KEY='cinpsi_jornada_motivos', JR_MOTIVOS=['Alta','Desistência','Trocou especialidade'];
function jrMotivos(){ return load(JR_MOT_KEY)||{}; }
function jrSetMotivo(k,v){ const m=Object.assign({},jrMotivos()); if(v) m[k]=v; else delete m[k]; store(JR_MOT_KEY,m); jrLista(); }
function jrMotivoSel(nome){
  const k=jrNz(nome), cur=jrMotivos()[k]||'';
  return '<select onchange="jrSetMotivo(decodeURIComponent(\''+encodeURIComponent(k)+'\'),this.value)" style="font-size:12px;padding:4px 6px;border:1px solid var(--border);border-radius:8px;background:'+(cur?'#fff':'#FFF7E6')+'"><option value="">Selecionar…</option>'
    +JR_MOTIVOS.map(o=>'<option'+(cur===o?' selected':'')+'>'+o+'</option>').join('')+'</select>';
}
function jrResumoMotivos(pa){
  const m=jrMotivos(), c={}; let sem=0;
  pa.forEach(p=>{ const v=m[jrNz(p.nome)]; if(v) c[v]=(c[v]||0)+1; else sem++; });
  return '<div style="font-size:12.5px;color:var(--text2);margin-bottom:8px">Motivo da parada: '+JR_MOTIVOS.map(o=>'<strong>'+o+'</strong> '+(c[o]||0)).join(' · ')+' · <strong>sem motivo</strong> '+sem+'</div>';
}
